INSERT INTO fc_sbc_formations VALUES('FC27',105,'4-3-3','FUTWIZ 세트 페이지 FORMATION 「433」 (https://www.futwiz.com/sbcs/future-stars-challenge-4/65 · URL 번호 65 = EA set_ea_id · 세트 내 챌린지 1개 = challenge_ea_id 105 · 2026-10-22) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — FUTWIZ 표기 「433」을 변형 번호 없는 4-3-3으로 읽었다(변형이면 「433(4)」식일 것으로 본 해석 · 미검증). 조건 원문 6개 fut.gg와 일치. 인게임 기록과 갈리면 인게임 우선','2026-10-21');
INSERT INTO fc_sbc_formations VALUES('FC27',106,'4-4-2','FUTWIZ 세트 페이지 FORMATION 「442」 · TOTAL PLAYERS 10 (https://www.futwiz.com/sbcs/1-of-3-79-gold-player-pick/66 · URL 번호 66 = EA set_ea_id · 세트 내 챌린지 1개 = challenge_ea_id 106 · 2026-10-22) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — FUTWIZ 표기 「442」를 4-4-2로 읽었다. 조건 원문(Min Gold · 10명) fut.gg와 일치. 인게임 기록과 갈리면 인게임 우선','2026-10-21');
INSERT INTO fc_sbc_formations VALUES('FC27',99,'4-4-2','FUTWIZ 세트 페이지 FORMATION 「442」 · TOTAL PLAYERS 11 (https://www.futwiz.com/sbcs/marquee-matchups/59 · URL 번호 59 = EA set_ea_id · 세트 내 챌린지 4개라 FUTWIZ 챌린지 번호(/sbcs/squads/fc-barcelona-v-real-madrid/120)는 EA id가 아님 → 같은 EA 세트 안에서 챌린지 이름 + 조건 원문 전항 일치로 challenge_ea_id 99에 연결 · 2026-10-23) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — 연결: 세트 id(EA)는 번호로, 챌린지는 이름+조건 원문(팀 레이팅 75·케미 26·같은 국적 3·리그 4+·같은 클럽 최대 4·바르사/레알 2) 전항 일치로 확인(번호 조인 아님 · 세트 내 이름 유일). 표기: FUTWIZ 「442」를 변형 번호 없는 4-4-2로 읽었다(10-22 선례와 같은 해석 · 미검증). 인게임 기록과 갈리면 인게임 우선','2026-10-23');
INSERT INTO fc_sbc_formations VALUES('FC27',98,'4-5-1','FUTWIZ 세트 페이지 FORMATION 「451」 · TOTAL PLAYERS 11 (https://www.futwiz.com/sbcs/marquee-matchups/59 · URL 번호 59 = EA set_ea_id · 세트 내 챌린지 4개라 FUTWIZ 챌린지 번호(/sbcs/squads/chelsea-v-tottenham-hotspur/119)는 EA id가 아님 → 같은 EA 세트 안에서 챌린지 이름 + 조건 원문 전항 일치로 challenge_ea_id 98에 연결 · 2026-10-23) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — 연결: 세트 id(EA)는 번호로, 챌린지는 이름+조건 원문(케미 22·같은 리그 4·같은 클럽 최대 3·첼시/스퍼스 2·골드 2·최소 실버) 전항 일치로 확인(번호 조인 아님 · 세트 내 이름 유일). 표기: FUTWIZ 「451」를 변형 번호 없는 4-5-1로 읽었다(10-22 선례와 같은 해석 · 미검증). 인게임 기록과 갈리면 인게임 우선','2026-10-23');
INSERT INTO fc_sbc_formations VALUES('FC27',97,'5-3-2','FUTWIZ 세트 페이지 FORMATION 「532」 · TOTAL PLAYERS 11 (https://www.futwiz.com/sbcs/marquee-matchups/59 · URL 번호 59 = EA set_ea_id · 세트 내 챌린지 4개라 FUTWIZ 챌린지 번호(/sbcs/squads/ssc-napoli-v-as-roma/118)는 EA id가 아님 → 같은 EA 세트 안에서 챌린지 이름 + 조건 원문 전항 일치로 challenge_ea_id 97에 연결 · 2026-10-23) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — 연결: 세트 id(EA)는 번호로, 챌린지는 이름+조건 원문(케미 18·리그 최대 6·같은 클럽 2·나폴리/로마 1·골드 2·최소 실버) 전항 일치로 확인(번호 조인 아님 · 세트 내 이름 유일). 표기: FUTWIZ 「532」를 변형 번호 없는 5-3-2로 읽었다(10-22 선례와 같은 해석 · 미검증). 인게임 기록과 갈리면 인게임 우선','2026-10-23');
INSERT INTO fc_sbc_formations VALUES('FC27',96,'5-2-1-2','FUTWIZ 세트 페이지 FORMATION 「5212」 · TOTAL PLAYERS 11 (https://www.futwiz.com/sbcs/marquee-matchups/59 · URL 번호 59 = EA set_ea_id · 세트 내 챌린지 4개라 FUTWIZ 챌린지 번호(/sbcs/squads/psg-v-olympique-lyonnais/117)는 EA id가 아님 → 같은 EA 세트 안에서 챌린지 이름 + 조건 원문 전항 일치로 challenge_ea_id 96에 연결 · 2026-10-23) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — 연결: 세트 id(EA)는 번호로, 챌린지는 이름+조건 원문(케미 14·클럽 4+·PSG/OL 1·실버 3·최소 브론즈) 전항 일치로 확인(번호 조인 아님 · 세트 내 이름 유일). 표기: FUTWIZ 「5212」를 변형 번호 없는 5-2-1-2로 읽었다(10-22 선례와 같은 해석 · 미검증). 인게임 기록과 갈리면 인게임 우선','2026-10-23');
INSERT INTO fc_sbc_formations VALUES('FC27',112,'3-4-3','FUTWIZ 세트 페이지 FORMATION 「343」 · TOTAL PLAYERS 7 (https://www.futwiz.com/sbcs/spooky-nights/72 · URL 번호 72 = EA set_ea_id · 세트 내 챌린지 1개(FUTWIZ 챌린지 번호 /sbcs/squads/spooky-nights/124는 EA id 아님)라 challenge_ea_id 112로 연결 · 2026-10-24 예약 실행) — FUTBIN은 앱 안 브라우저에서 Cloudflare에 막혀 대체','MEDIUM — 연결: 세트 id(EA) 번호 + 세트당 챌린지 1개 + 조건 원문 일치(케미 14·같은 리그 최대 4·같은 국적 3·골드 3). 브릭 챌린지(7명)라 3-4-3 중 일부 칸만 채운다. 표기: FUTWIZ 「343」을 변형 번호 없는 3-4-3으로 읽었다(10-22 선례와 같은 해석 · 미검증). 인게임 기록과 갈리면 인게임 우선','2026-10-24');
